     require(amount > 0, "USDO: amount not valid");
     uint256 fee = flashFee(token, amount);
      _mint(address(receiver), amount);

      require(receiver.onFlashLoan(msg.sender, token, amount, fee, data) ==  FLASH_MINT_CALLBACK_SUCCESS, "USDO: failed");

